/// The text of each built-in component.yaml, by folder name.
const builtinComponentFiles = <String, String>{
  "Button":
      "# A button the user clicks: its Caption is the text on it, and Click\n# runs when it is clicked.\nname: Button\nversion: 1\nvisual: true\ndefaultEvent: Click\nproperties:\n  - { name: Caption, type: String, default: \"\" }\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 96 }\n  - { name: Height, type: Integer, min: 0, default: 32 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Click()\n  # A mouse button pressed and let go on it (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  Text: Caption\n# The type's name in other versions of BASIC (A056, F020, D104).\naliases: [CommandButton]\n",
  "CheckBox":
      "# A box the user checks and unchecks, with a Caption beside it\n# (docs/DESIGN.md D44). Changed runs after Checked changes, also when the\n# program sets Checked (changeEvent), as TextBox.Changed does.\nname: CheckBox\nversion: 1\nvisual: true\ndefaultEvent: Changed\nproperties:\n  - { name: Caption, type: String, default: \"\" }\n  - { name: Checked, type: Boolean, default: false, changeEvent: Changed }\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 120 }\n  - { name: Height, type: Integer, min: 0, default: 32 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Changed()\n  # A mouse button pressed and let go on it (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  Text: Caption\n  Value: Checked\n# Events other versions of BASIC name differently (A051, D100).\notherEvents:\n  CheckedChanged: Changed\n",
  "ComboBox":
      "# A closed list that opens to pick one item (docs/DESIGN.md D104): Visual\n# Basic 6's ComboBox with Style 2, the user picks and does not type. The\n# program fills it and reads it as a ListBox (D46): AddItem, List,\n# ListCount, ListIndex and Text, and Changed runs whenever ListIndex\n# changes.\nname: ComboBox\nversion: 1\nvisual: true\ndefaultEvent: Changed\nproperties:\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 160 }\n  - { name: Height, type: Integer, min: 0, default: 32 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\n  # -1 when nothing is chosen; set only while the program runs (D45).\n  - name: ListIndex\n    type: Integer\n    default: -1\n    min: -1\n    designTime: false\n    changeEvent: Changed\n  - { name: ListCount, type: Integer, default: 0, readOnly: true }\n  - { name: Text, type: String, default: \"\", readOnly: true }\n  - { name: Items, type: List(Of String), default: [], internal: true }\nevents:\n  - Changed()\n  # A mouse button pressed and let go on it (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods:\n  - AddItem(item As String)\n  - RemoveItem(index As Integer)\n  - Clear()\n  - List(index As Integer) As String\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  SelectedIndex: ListIndex\n  Items: [AddItem, List, ListCount]\n# Events other versions of BASIC name differently (A051, D100).\notherEvents:\n  SelectedIndexChanged: Changed\n  Click: Changed\n",
  "Database":
      "# Keeps a program's data in an SQLite database file (docs/DESIGN.md D124,\n# D126), the way Visual Basic 6 kept it in a Jet database through Data\n# Access Objects\n# (https://learn.microsoft.com/en-us/previous-versions/visualstudio/visual-basic-6/aa227845(v=vs.60)).\n# A built-in object used by its name, not put on a form. Every app has a\n# database of its own, data.db in the app's own data folder, opened when\n# first used; Database.Open(name) opens another file there instead.\n# Execute(sql, values…) runs a statement and gives how many rows it\n# changed; Query(sql, values…) gives the rows as a Table; Scalar(sql,\n# values…) gives the first value of the first row as text, \"\" for NULL or\n# no row, and LastWasNull says which. A value goes into the SQL as a ?,\n# and after it in the call: Database.Execute(\"INSERT INTO scores(name,\n# points) VALUES (?, ?)\", txtName.Text, points); a quote in the value\n# then cannot break the statement. Integer, Double and String go in as\n# they are, Boolean as 1 or 0, Date as \"yyyy-MM-dd HH:mm:ss\", Nothing as\n# NULL. LastId is the row ID the last INSERT gave; Path is where the file\n# is; Close() closes it (the next use opens it again). SQL the database\n# cannot run is R042; a name that is not a file name is R043; a database\n# that cannot be opened is R044. SQL joined with & is a warning (A060).\nname: Database\nversion: 1\nobject: true\nplatforms: [web, macos, windows]\nproperties:\n  # Where the open database file is: on the desktop its full path, on the\n  # web its name in the browser's storage.\n  - { name: Path, type: String, default: \"\", readOnly: true }\n  # Whether the last Scalar found NULL, or no row at all.\n  - { name: LastWasNull, type: Boolean, default: false, readOnly: true }\n  # The row ID of the last INSERT (SQLite's last_insert_rowid).\n  - { name: LastId, type: Integer, default: 0, readOnly: true }\nevents: []\nmethods:\n  - Open(name As String)\n  - Execute(sql As String, ParamArray values As Value) As Integer\n  - Query(sql As String, ParamArray values As Value) As Table\n  - Scalar(sql As String, ParamArray values As Value) As String\n  - Close()\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50): Data Access Objects' and ADO's.\notherNames:\n  OpenDatabase: Open\n  OpenRecordset: Query\n  ExecuteNonQuery: Execute\n  ExecuteScalar: Scalar\n",
  "Form":
      "# The form a program's controls sit on (docs/DESIGN.md §5).\n# Width and Height are the size of the area inside the window. Resize runs\n# when it changes, and once when the form is first shown (D58).\n# Integer properties are 32-bit (min and max narrow that); a value outside\n# is a run-time error (R007) or, in a form file, F012.\n# A project's forms are shown one over another (docs/DESIGN.md D88): Show\n# puts the form in front, ShowDialog puts it in front as a dialog and waits\n# until it goes, Hide takes it away keeping its values, Close takes it away\n# and starts it again the next time it is shown. Closed runs after Close.\nname: Form\nversion: 1\nvisual: true\ndefaultEvent: Load\nproperties:\n  - { name: Caption, type: String, default: \"\" }\n  - { name: Width, type: Integer, min: 0, default: 480, changeEvent: Resize }\n  - { name: Height, type: Integer, min: 0, default: 360, changeEvent: Resize }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\n  # Whether KeyDown and KeyUp come also while a TextBox is typed in, before\n  # the TextBox gets the key (D101).\n  - { name: KeyPreview, type: Boolean, default: false }\n  # How a dialog was closed (D103): DialogResult.OK, .Cancel, .Yes, .No or\n  # .None (0). Set while the form is shown by ShowDialog, it closes it.\n  - { name: DialogResult, type: Integer, min: 0, max: 7, default: 0, designTime: false }\nevents:\n  - Load()\n  - Resize()\n  - Closed()\n  # A key pressed (again while held) and let go, while the form is in\n  # front (D101).\n  - KeyDown(e As KeyEventArgs)\n  - KeyUp(e As KeyEventArgs)\n  # A mouse button pressed and let go where no control is (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods:\n  - Show()\n  - ShowDialog() As Integer\n  - Hide()\n  - Close()\n  # Shows the items of one of the form's menus where the mouse last went\n  # down on it, and waits until one is chosen, or none (D106).\n  - PopupMenu(menu As Menu)\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  Text: Caption\n",
  "Frame":
      "# A box with a Caption on its edge that holds other controls\n# (docs/DESIGN.md D105). The controls in it are placed from its top-left\n# corner, anchored to its edges, and move with it; its OptionButtons are a\n# group of their own, as in Visual Basic 6.\nname: Frame\nversion: 1\nvisual: true\ncontainer: true\ndefaultEvent: Click\nproperties:\n  - { name: Caption, type: String, default: \"\" }\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 200 }\n  - { name: Height, type: Integer, min: 0, default: 120 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Click()\n  # A mouse button pressed and let go on it (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  Text: Caption\n# The type's name in Visual Basic .NET (A056, F020, D104).\naliases: [GroupBox]\n",
  "Grid":
      "# A table of text the user reads and edits (docs/DESIGN.md D116), as\n# Visual Basic's grids: named columns, rows and columns counted from 0,\n# the header row not among them. A click chooses a cell (Row, Col) and\n# runs Click; a second click on it, Enter, F2 or typing edits it unless\n# ReadOnly, and Changed runs when the user has changed it, Row and Col on\n# that cell. The program's\n# own changes run nothing. LoadCsv and SaveCsv read and write it as a\n# CSV file, as Csv.Read and Csv.Write do (D114).\nname: Grid\nversion: 1\nvisual: true\ndefaultEvent: Changed\nproperties:\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 320 }\n  - { name: Height, type: Integer, min: 0, default: 160 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  - { name: ReadOnly, type: Boolean, default: false }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\n  # The chosen cell; -1 when none. Set only while the program runs.\n  - { name: Row, type: Integer, default: -1, min: -1, designTime: false }\n  - { name: Col, type: Integer, default: -1, min: -1, designTime: false }\n  - { name: RowCount, type: Integer, default: 0, readOnly: true }\n  - { name: ColumnCount, type: Integer, default: 0, readOnly: true }\n  # The column names, and the cells row by row.\n  - { name: Headers, type: List(Of String), default: [], internal: true }\n  - { name: Cells, type: List(Of String), default: [], internal: true }\n  # Each column's width in pixels, as text; 0, or none, shares what is\n  # left (D118).\n  - { name: ColumnWidths, type: List(Of String), default: [], internal: true }\nevents:\n  - Changed()\n  - Click()\n  # A mouse button pressed and let go on it (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods:\n  - Cell(row As Integer, column As Column) As String Settable\n  - Header(column As Integer) As String Settable\n  # A column's width in pixels; 0 (at first) shares what the columns with\n  # a width leave (D118).\n  - ColumnWidth(column As Integer) As Integer Settable\n  - Column(name As String) As Integer\n  - AddRow() As Integer\n  - AddColumn(name As String)\n  - Clear()\n  - LoadCsv(path As String)\n  - SaveCsv(path As String)\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  TextMatrix: Cell\n  Rows: RowCount\n  Cols: ColumnCount\n  ColWidth: ColumnWidth\n  CurrentRow: Row\n# Events other versions of BASIC name differently (A051, D100).\notherEvents:\n  CellValueChanged: Changed\n  CellClick: Click\n# The names of Visual Basic .NET's and Visual Basic 6's grids (A056, F020).\naliases: [DataGridView, MSFlexGrid]\n",
  "Http":
      "# Talks to web servers over HTTP (docs/DESIGN.md D124, D125), the way\n# Visual Basic 6's Internet Transfer Control did with OpenURL\n# (https://learn.microsoft.com/en-us/previous-versions/visualstudio/visual-basic-6/aa733648(v=vs.60)). A built-in\n# object used by its name, not put on a form: Http.Get(url) gives the\n# answer's text, Http.GetJson(url) its JSON, Http.Post(url, body) and\n# Http.PostJson(url, json) send a body and give the answer, and\n# Http.Send(method, url, body) gives the whole answer as an HttpResponse,\n# whatever its status. A call waits where it is, as File.ReadAllText\n# does: the screen keeps drawing, the pointer shows waiting, and clicks\n# made meanwhile run after it, in turn. Header(name) is a header sent\n# with every request from then on (\"\" takes it away); Timeout is how many\n# seconds to wait for an answer. A request that gets no answer is R036; a\n# status from 400 is R037 in all but Send; text that is not JSON is R039.\n# The first component through the component channel\n# (docs/COMPONENT_CHANNEL.md).\nname: Http\nversion: 1\nobject: true\nplatforms: [web, macos, windows]\nproperties:\n  # Seconds to wait for the answer, from 1 to 600.\n  - { name: Timeout, type: Integer, min: 1, max: 600, default: 30 }\nevents: []\nmethods:\n  - Get(url As String) As String\n  - Post(url As String, body As String) As String\n  - GetJson(url As String) As Json\n  - PostJson(url As String, body As Json) As Json\n  - Send(method As String, url As String, body As String) As HttpResponse\n  - Header(name As String) As String Settable\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50): the Internet Transfer Control's.\notherNames:\n  OpenURL: Get\n  Execute: Send\n  RequestTimeout: Timeout\n",
  "Image":
      "# A picture from the project (docs/DESIGN.md D51). Picture names one of\n# the project's pictures (pictures/ in its folder), in any case; \"\" shows\n# none. Stretch: True fills the control, maybe changing the picture's\n# proportions; False (the default) fits the whole picture inside, keeping\n# them. Unlike Visual Basic 6, the control never changes its own size to\n# the picture's. Drawn under the other controls, like a Label.\nname: Image\nversion: 1\nvisual: true\nlayer: graphic\ndefaultEvent: Click\nproperties:\n  - { name: Picture, type: String, default: \"\", picture: true }\n  - { name: Stretch, type: Boolean, default: false }\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 120 }\n  - { name: Height, type: Integer, min: 0, default: 120 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Click()\n  # A mouse button pressed and let go on it (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  Image: Picture\n  SizeMode: Stretch\n# The type's name in other versions of BASIC (A056, F020, D104).\naliases: [PictureBox]\n",
  "Label":
      "# Text on the form that the user reads but does not type into: its\n# Caption. Click runs when it is clicked.\nname: Label\nversion: 1\nvisual: true\n# Drawn under Buttons and TextBoxes, whatever the order (DESIGN.md D41).\nlayer: graphic\ndefaultEvent: Click\nproperties:\n  - { name: Caption, type: String, default: \"\" }\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 120 }\n  - { name: Height, type: Integer, min: 0, default: 24 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Click()\n  # A mouse button pressed and let go on it (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  Text: Caption\n",
  "ListBox":
      "# A list the user picks one item from (docs/DESIGN.md D46). The program\n# fills it with AddItem and reads it with List, ListCount, ListIndex and\n# Text. Changed runs whenever ListIndex changes: the user picks an item,\n# the program sets ListIndex, or RemoveItem / Clear changes it.\n# Items are set only in code for now (docs/KNOWN_ISSUES.md).\nname: ListBox\nversion: 1\nvisual: true\ndefaultEvent: Changed\nproperties:\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 160 }\n  - { name: Height, type: Integer, min: 0, default: 120 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\n  # -1 when nothing is chosen; set only while the program runs (D45).\n  - name: ListIndex\n    type: Integer\n    default: -1\n    min: -1\n    designTime: false\n    changeEvent: Changed\n  - { name: ListCount, type: Integer, default: 0, readOnly: true }\n  - { name: Text, type: String, default: \"\", readOnly: true }\n  - { name: Items, type: List(Of String), default: [], internal: true }\nevents:\n  - Changed()\n  # A mouse button pressed and let go on it (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods:\n  - AddItem(item As String)\n  - RemoveItem(index As Integer)\n  - Clear()\n  - List(index As Integer) As String\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  SelectedIndex: ListIndex\n  Items: [AddItem, List, ListCount]\n# Events other versions of BASIC name differently (A051, D100).\notherEvents:\n  SelectedIndexChanged: Changed\n  Click: Changed\n",
  "Menu":
      "# An item of a form's menu bar (docs/DESIGN.md D106), made in the menu\n# editor and written under menus: in the form file. A menu with items in\n# it opens them; an item without opens nothing and raises Click. A\n# Caption of \"-\" is a line between items. Ctrl in a Shortcut is the\n# Command key on macOS. Not seen on the form: the window draws the menu\n# bar, or on macOS the system's menu bar does.\nname: Menu\nversion: 1\nvisual: false\nmenu: true\ndefaultEvent: Click\nproperties:\n  - { name: Caption, type: String, default: \"\" }\n  - { name: Checked, type: Boolean, default: false }\n  - { name: Enabled, type: Boolean, default: true }\n  # False: not on the menu bar, or not in its menu; a menu that is not\n  # Visible can still be shown with PopupMenu.\n  - { name: Visible, type: Boolean, default: true }\n  - { name: Shortcut, type: String, default: \"\", shortcut: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Click()\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  Text: Caption\n",
  "OpenFileDialog":
      "# The dialog that asks for a file to open (docs/DESIGN.md D113), as Visual\n# Basic .NET's OpenFileDialog. Not seen on the form: the designer keeps it\n# in the tray. ShowDialog() shows it and gives DialogResult.OK with the\n# file in FileName, after FileOk has run, or DialogResult.Cancel. Filter\n# is \"Text files|*.txt|All files|*.*\": a label and its patterns, in pairs.\n# On the web FileName is the file's name, which the File functions take\n# in the same run; the file is read from the browser.\nname: OpenFileDialog\nversion: 1\nvisual: false\ndefaultEvent: FileOk\nproperties:\n  - { name: Title, type: String, default: \"\" }\n  - { name: Filter, type: String, default: \"\" }\n  - { name: FileName, type: String, default: \"\" }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - FileOk()\nmethods:\n  - ShowDialog() As Integer\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  Index: Tag\n",
  "OptionButton":
      "# One of a group of choices, of which one is checked (docs/DESIGN.md\n# D104): the OptionButtons of a form are one group. Checking one, by a\n# click or in code, unchecks the others. Changed runs when it becomes\n# checked, as Visual Basic 6's Click did; the ones it unchecks raise\n# nothing, so one handler for the whole group runs once.\nname: OptionButton\nversion: 1\nvisual: true\ndefaultEvent: Changed\nproperties:\n  - { name: Caption, type: String, default: \"\" }\n  - { name: Checked, type: Boolean, default: false, changeEvent: Changed }\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 120 }\n  - { name: Height, type: Integer, min: 0, default: 32 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Changed()\n  # A mouse button pressed and let go on it (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n  Text: Caption\n  Value: Checked\n# Events other versions of BASIC name differently (A051, D100).\notherEvents:\n  CheckedChanged: Changed\n  Click: Changed\n# The type's name in Visual Basic .NET (A056, F020, D104).\naliases: [RadioButton]\n",
  "SaveFileDialog":
      "# The dialog that asks for a file to save to (docs/DESIGN.md D113), as Visual\n# Basic .NET's SaveFileDialog. Not seen on the form: the designer keeps it\n# in the tray. ShowDialog() shows it and gives DialogResult.OK with the\n# file in FileName, after FileOk has run, or DialogResult.Cancel. Filter\n# is \"Text files|*.txt|All files|*.*\": a label and its patterns, in pairs.\n# On the web FileName is the file's name, which the File functions take\n# in the same run; saving downloads the file under it.\nname: SaveFileDialog\nversion: 1\nvisual: false\ndefaultEvent: FileOk\nproperties:\n  - { name: Title, type: String, default: \"\" }\n  - { name: Filter, type: String, default: \"\" }\n  - { name: FileName, type: String, default: \"\" }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - FileOk()\nmethods:\n  - ShowDialog() As Integer\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  Index: Tag\n",
  "TextBox":
      "# A box the user types a line of text into: its Text.\n# Changed runs after the text changes, also when the program sets Text\n# (changeEvent). Text holds only the characters the input method (IME)\n# has committed, and Changed runs each time it commits one\n# (docs/LANGUAGE.md §11.1).\nname: TextBox\nversion: 1\nvisual: true\ndefaultEvent: Changed\nproperties:\n  - { name: Text, type: String, default: \"\", changeEvent: Changed }\n  - { name: Left, type: Integer, default: 0 }\n  - { name: Top, type: Integer, default: 0 }\n  - { name: Width, type: Integer, min: 0, default: 160 }\n  - { name: Height, type: Integer, min: 0, default: 32 }\n  # The edges of the form, or of the Frame it is in, whose distance it\n  # keeps (D57, D105).\n  - { name: Anchor, type: String, default: \"Left Top\", anchor: true }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Changed()\n  # A mouse button pressed and let go on it (D111).\n  - MouseDown(e As MouseEventArgs)\n  - MouseUp(e As MouseEventArgs)\nmethods: []\n# Names other versions of BASIC use, pointed to GuBASIC's (A036,\n# docs/DESIGN.md D50).\notherNames:\n  # Visual Basic 6's control arrays numbered controls; a Tag can (D99).\n  Index: Tag\n# Events other versions of BASIC name differently (A051, D100).\notherEvents:\n  TextChanged: Changed\n  Change: Changed\n",
  "Timer":
      "# A Timer runs its Tick every Interval milliseconds while Enabled\n# (docs/DESIGN.md D82, D100). It is not seen on the form: the designer\n# keeps it in a tray under the form, so it has no place or size. A tick\n# is an event like a click: it does not re-enter, and waits while another\n# handler runs. Start and Stop set Enabled.\nname: Timer\nversion: 1\nvisual: false\ndefaultEvent: Tick\nproperties:\n  # How often Tick runs, in milliseconds; at least 1.\n  - { name: Interval, type: Integer, min: 1, default: 100 }\n  # Off at first, as in Visual Basic .NET, so that no tick comes before\n  # Form_Load has set things up.\n  - { name: Enabled, type: Boolean, default: false }\n  # Any text the program keeps with it, as in Visual Basic; GuBASIC does\n  # nothing with it (D98).\n  - { name: Tag, type: String, default: \"\" }\nevents:\n  - Tick()\nmethods:\n  - Start()\n  - Stop()\n# Names other versions of BASIC use, pointed to GuBASIC's (A036, A051,\n# docs/DESIGN.md D50).\notherEvents:\n  # Visual Basic 6 called the event Timer: Timer1_Timer.\n  Timer: Tick\n",
};
